     * @param int|float|null $windowWidth Window width. Window width in metres (0.1–50 m, canonical metric regardless of HA locale). Vertical blind only. 0.1 to 50 m
     */
    public function setGeometry(
        ServiceTargetSource $target,
        int|float|null $angle = null,
        int|float|null $lengthAwning = null,
        int|float|null $sillHeight = null,
        int|float|null $slatDepth = null,
        int|float|null $slatDistance = null,
        int|float|null $tiltAngle0 = null,
        int|float|null $tiltAngle100 = null,
        int|float|null $tiltHorizontalPercent = null,
        ?string $tiltMode = null,
        int|float|null $windowDepth = null,
        int|float|null $windowHeight = null,
        int|float|null $windowWidth = null,
    ): EventContext {
        return $this->ha->callService('adaptive_cover_pro', 'set_geometry', [
            'angle' => $angle,
            'length_awning' => $lengthAwning,
            'sill_height' => $sillHeight,
            'slat_depth' => $slatDepth,
            'slat_distance' => $slatDistance,
            'tilt_angle_0' => $tiltAngle0,
            'tilt_angle_100' => $tiltAngle100,
            'tilt_horizontal_percent' => $tiltHorizontalPercent,
            'tilt_mode' => $tiltMode,
            'window_depth' => $windowDepth,
            'window_height' => $windowHeight,
            'window_width' => $windowWidth,
        ], $target);
    }

    /**
     * Set interpolation
     *
     * Enable position interpolation and configure the start/end range and lookup table.
     *
     * @param ?bool $interp Enable interpolation. If true, apply interpolation mapping to the calculated position
     * @param int|float|null $interpEnd Interpolation end. Calculated position (%) at which interpolation ends. Null = none. 0 to 100 %
     * @param string|int|float|null $interpList Interpolation input list. List of input positions (strings) for the interpolation lookup table
     * @param string|int|float|null $interpListNew Interpolation output list. List of output positions (strings) mapped from interp_list
     * @param int|float|null $interpStart Interpolation start. Calculated position (%) at which interpolation begins. Null = none. 0 to 100 %
     */
    public function setInterpolation(
        ServiceTargetSource $target,
        ?bool $interp = null,
        int|float|null $interpEnd = null,
        string|int|float|null $interpList = null,
        string|int|float|null $interpListNew = null,
        int|float|null $interpStart = null,
    ): EventContext {
        return $this->ha->callService('adaptive_cover_pro', 'set_interpolation', [
            'interp' => $interp,
            'interp_end' => $interpEnd,
            'interp_list' => $interpList,
            'interp_list_new' => $interpListNew,
            'interp_start' => $interpStart,
        ], $target);
    }

    /**
     * Set light & cloud settings
     *
     * Update weather entity, sunny-state filter, lux/irradiance thresholds, cloud coverage threshold, and the cloud suppression toggle.
     *
     * @param ?string $cloudCoverageEntity Cloud coverage sensor. Sensor reporting cloud coverage percentage. Null = none
     * @param int|float|null $cloudCoverageThreshold Cloud coverage threshold. Cloud coverage percentage above which the sky is considered overcast. 0 to 100 %
     * @param ?bool $cloudSuppression Enable cloud suppression. If true, suppress solar positioning when cloud coverage exceeds the threshold
     * @param ?string $irradianceEntity Irradiance sensor. Solar irradiance sensor entity. Null = none
     * @param int|float|null $irradianceThreshold Irradiance threshold. W/m² above which the cover is considered in direct sunlight. 0 to 2000 W/m²
     * @param ?string $isSunnySensor Is Sunny binary sensor. Binary entity that authoritatively reports sun-on-window. ON = sunny, OFF = cloud suppression fires. Unavailable falls back to weather state. Null = none
     * @param ?string $luxEntity Lux sensor. Illuminance sensor entity. Null = none
     * @param int|float|null $luxThreshold Lux threshold. Lux value above which the cover is considered in direct sunlight. 0 to 100000 lux
     * @param ?string $weatherEntity Weather entity. Weather entity used to read conditions (domain: weather). Null = none
     * @param list<'clear-night'|'clear'|'cloudy'|'fog'|'hail'|'lightning'|'lightning-rainy'|'partlycloudy'|'pouring'|'rainy'|'snowy'|'snowy-rainy'|'sunny'|'windy'|'windy-variant'|'exceptional'>|null $weatherState Sunny weather states. Weather condition states considered 'sunny' for sun-tracking purposes
     */
    public function setLightCloud(
        ServiceTargetSource $target,
        ?string $cloudCoverageEntity = null,
        int|float|null $cloudCoverageThreshold = null,
        ?bool $cloudSuppression = null,
        ?string $irradianceEntity = null,
        int|float|null $irradianceThreshold = null,
        ?string $isSunnySensor = null,
        ?string $luxEntity = null,
        int|float|null $luxThreshold = null,
        ?string $weatherEntity = null,
        ?array $weatherState = null,
    ): EventContext {
        return $this->ha->callService('adaptive_cover_pro', 'set_light_cloud', [
            'cloud_coverage_entity' => $cloudCoverageEntity,
            'cloud_coverage_threshold' => $cloudCoverageThreshold,
            'cloud_suppression' => $cloudSuppression,
            'irradiance_entity' => $irradianceEntity,
            'irradiance_threshold' => $irradianceThreshold,
            'is_sunny_sensor' => $isSunnySensor,
            'lux_entity' => $luxEntity,
            'lux_threshold' => $luxThreshold,
            'weather_entity' => $weatherEntity,
            'weather_state' => $weatherState,
        ], $target);
    }

    /**
     * Set manual override settings
     *
     * Update manual override duration, reset behavior, and detection threshold.
     *
     * @param ?bool $manualIgnoreExternal Only engage from ACP commands. If true, only commands routed through the ACP proxy entity or the adaptive_cover_pro.set_position service engage manual override; all other position changes are ignored
     * @param ?bool $manualIgnoreIntermediate Ignore intermediate states. If true, ignore opening/closing transitional states for manual override detection
     * @param array{days?: int|float, hours?: int|float, minutes?: int|float, seconds?: int|float, milliseconds?: int|float}|string|int|float|null $manualOverrideDuration Override duration. How long a manual override lasts before automatic control resumes
     * @param 'fixed'|'until_sunset'|'until_sunrise'|'until_next_sun_event'|'until_window_end'|null $manualOverrideDurationMode Override duration mode. What the hold is measured against. "fixed" uses the duration above. The other modes hold until the next sunset, sunrise, sun event, or operating-window end after the moment you moved the cover, and fall back to the duration above when that boundary cannot be resolved
     * @param ?bool $manualOverrideReset Reset override on time window start. If true, clear any active manual override when the time window starts
     * @param int|float|null $manualThreshold Manual detection threshold. Position change (%) that triggers manual override detection (0–99). Null = any change. 0 to 99 %
     */
    public function setManualOverride(
        ServiceTargetSource $target,
        ?bool $manualIgnoreExternal = null,
        ?bool $manualIgnoreIntermediate = null,
        array|string|int|float|null $manualOverrideDuration = null,
        ?string $manualOverrideDurationMode = null,
        ?bool $manualOverrideReset = null,
        int|float|null $manualThreshold = null,
    ): EventContext {
        return $this->ha->callService('adaptive_cover_pro', 'set_manual_override', [
            'manual_ignore_external' => $manualIgnoreExternal,
            'manual_ignore_intermediate' => $manualIgnoreIntermediate,
            'manual_override_duration' => $manualOverrideDuration,
            'manual_override_duration_mode' => $manualOverrideDurationMode,
            'manual_override_reset' => $manualOverrideReset,
            'manual_threshold' => $manualThreshold,
        ], $target);
    }

    /**
     * Set occupancy settings (deprecated)
     *
     * Deprecated — use set_occupancy instead. Update occupancy sensors and occupancy timeout. Pass an empty list to disable occupancy detection. This service keeps working but will be removed in a future major release.
     *
     * @param list<string>|null $motionSensors Occupancy sensors. Binary sensors (motion/occupancy/presence device classes) that indicate occupancy. Empty list = disable
     * @param int|float|null $motionTimeout Occupancy timeout. Seconds to wait after occupancy clears before applying the occupancy-timeout position (30–3600). 30 to 3600 seconds
     */
    public function setMotion(
        ServiceTargetSource $target,
        ?array $motionSensors = null,
        int|float|null $motionTimeout = null,
    ): EventContext {
        return $this->ha->callService('adaptive_cover_pro', 'set_motion', [
            'motion_sensors' => $motionSensors,
            'motion_timeout' => $motionTimeout,
        ], $target);
    }

    /**
     * Set occupancy settings
     *
     * Update the occupancy sensors, media players, and timeout that drive occupancy detection. Pass an empty list to disable a source. Replaces the deprecated set_motion service.
     *
     * @param list<string>|null $occupancyMediaPlayers Occupancy media players. Media players treated as occupancy — any player that is not off counts as occupied. Empty list = disable
     * @param list<string>|null $occupancySensors Occupancy sensors. Binary sensors (motion/occupancy/presence device classes) that indicate occupancy. Empty list = disable
     * @param int|float|null $occupancyTimeout Occupancy timeout. Seconds to wait after occupancy clears before applying the occupancy-timeout position (30–3600). 30 to 3600 seconds
     */
    public function setOccupancy(
        ServiceTargetSource $target,
        ?array $occupancyMediaPlayers = null,
        ?array $occupancySensors = null,
        int|float|null $occupancyTimeout = null,
    ): EventContext {
        return $this->ha->callService('adaptive_cover_pro', 'set_occupancy', [
            'occupancy_media_players' => $occupancyMediaPlayers,
            'occupancy_sensors' => $occupancySensors,
            'occupancy_timeout' => $occupancyTimeout,
        ], $target);
    }

    /**
     * Set option (generic)
     *
     * Generic escape hatch — update any single supported option by key name. Identity keys (name, mode, group, linked_device_id) are rejected. See the integration documentation for the full list of supported option keys.
     *
     * @param string|int|float $option Option key. The internal option key to update (e.g. 'default_percentage', 'sunset_position')
     * @param string|int|float $value Value. New value for the option. Pass null to clear an optional field
     */
    public function setOption(
        ServiceTargetSource $target,
        string|int|float $option,
        string|int|float $value,
    ): EventContext {
        return $this->ha->callService('adaptive_cover_pro', 'set_option', [
            'option' => $option,
            'value' => $value,
        ], $target);
    }

    /**
     * Set position
     *
     * Move the targeted covers to an explicit position. Clamps up to the highest active custom-position minimum-mode floor across all slots. By default the call engages manual override and respects the priority pipeline (so an active force_override or weather override still wins); set force=true to bypass the pipeline check and skip manual-override engagement.
     *
     * @param int|float $position Position. Target position (0–100%). 0 to 100 %
     * @param ?bool $force Force. When true, bypass the priority pipeline check and skip manual-override engagement. Default false — service calls respect force_override / weather and engage manual override like a dashboard slider
     */
    public function setPosition(ServiceTargetSource $target, int|float $position, ?bool $force = null): EventContext
    {
        return $this->ha->callService('adaptive_cover_pro', 'set_position', [
            'position' => $position,
            'force' => $force,
        ], $target);
    }

    /**
     * Set position limits
     *
     * Update position-limit options (default height, min/max position, open/close threshold, inverse state). Changes are persisted and take effect after reload.
     *
     * @param int|float|null $defaultPercentage Default height. Default cover position when sun is not visible (0–100%). 0 to 100 %
     * @param ?bool $enableMaxPosition Enable max position only during sun tracking. If true, max_position applies only while sun is tracked
     * @param ?bool $enableMinPosition Enable min position only during sun tracking. If true, min_position applies only while sun is tracked
     * @param ?bool $enablePositionMatching Enable position matching. If true, the reconciliation pass resends the target until the cover reaches it. If false (the default), the cover is commanded once and a settle past the position tolerance becomes a manual override
     * @param ?bool $inverseState Inverse state. Invert position (0%=open, 100%=closed) for covers that report state inversely
     * @param int|float|null $maxPosition Maximum position. Maximum position the cover may move to (0–100%; 0 = always closed). 0 to 100 %
     * @param int|float|null $minPosition Minimum position. Minimum position the cover may move to (0–99%). 0 to 99 %
     * @param int|float|null $minPositionSunTracking Min position during sun tracking. Optional separate minimum floor that applies only during sun tracking (0–99%). When set, overrides min_position for sun-tracking paths only. Leave unset to use min_position for all paths. 0 to 99 %
     * @param int|float|null $openCloseThreshold Open/close threshold. Position below which open/close-only covers are closed (1–99%). 1 to 99 %
     */
    public function setPositionLimits(
        ServiceTargetSource $target,
        int|float|null $defaultPercentage = null,
        ?bool $enableMaxPosition = null,
        ?bool $enableMinPosition = null,
        ?bool $enablePositionMatching = null,
        ?bool $inverseState = null,
        int|float|null $maxPosition = null,
        int|float|null $minPosition = null,
        int|float|null $minPositionSunTracking = null,
        int|float|null $openCloseThreshold = null,
    ): EventContext {
        return $this->ha->callService('adaptive_cover_pro', 'set_position_limits', [
            'default_percentage' => $defaultPercentage,
            'enable_max_position' => $enableMaxPosition,
            'enable_min_position' => $enableMinPosition,
            'enable_position_matching' => $enablePositionMatching,
            'inverse_state' => $inverseState,
            'max_position' => $maxPosition,
            'min_position' => $minPosition,
            'min_position_sun_tracking' => $minPositionSunTracking,
            'open_close_threshold' => $openCloseThreshold,
        ], $target);
    }

    /**
     * Set sun tracking settings
     *
     * Update azimuth, sun acceptance angle, elevation limits, and sun-tracking toggle.
     *
     * @param int|float|null $distanceShadedArea Distance to shaded area. Distance from the window to the edge of the shaded area in metres (0.1–50 m, canonical metric regardless of HA locale). 0.1 to 50 m
     * @param ?bool $enableSunTracking Enable sun tracking. Master toggle for solar-position-based cover control
     * @param int|float|null $fovLeft Sun acceptance angle — left. Degrees to the left of the azimuth within which the sun affects this cover (0–180°). 0 to 180 °
     * @param int|float|null $fovRight Sun acceptance angle — right. Degrees to the right of the azimuth within which the sun affects this cover (0–180°). 0 to 180 °
     * @param int|float|null $maxCoverageSteps Maximum coverage steps. Number of distinct positions used to reach full coverage when minimize_movements is on (1–10). 1 = jump straight to full coverage. 1 to 10
     * @param int|float|null $maxElevation Maximum sun elevation. Sun elevation (°) above which the cover is fully opened. Null = no maximum. 0 to 90 °
     * @param int|float|null $minElevation Minimum sun elevation. Sun elevation (°) below which the cover is not moved. Null = no minimum. 0 to 90 °
     * @param ?bool $minimizeMovements Minimize movements. If true, quantize the sun-tracked position into discrete coverage levels (rounding toward more coverage) to reduce motor movements
     * @param int|float|null $setAzimuth Window azimuth. Compass direction the window faces (0–359°). 0 to 359 °
     */
    public function setSunTracking(
        ServiceTargetSource $target,
        int|float|null $distanceShadedArea = null,
        ?bool $enableSunTracking = null,
        int|float|null $fovLeft = null,
        int|float|null $fovRight = null,
        int|float|null $maxCoverageSteps = null,
        int|float|null $maxElevation = null,
        int|float|null $minElevation = null,
        ?bool $minimizeMovements = null,
        int|float|null $setAzimuth = null,
    ): EventContext {
        return $this->ha->callService('adaptive_cover_pro', 'set_sun_tracking', [
            'distance_shaded_area' => $distanceShadedArea,
            'enable_sun_tracking' => $enableSunTracking,
            'fov_left' => $fovLeft,
            'fov_right' => $fovRight,
            'max_coverage_steps' => $maxCoverageSteps,
            'max_elevation' => $maxElevation,
            'min_elevation' => $minElevation,
            'minimize_movements' => $minimizeMovements,
            'set_azimuth' => $setAzimuth,
        ], $target);
    }

    /**
     * Set sunset / sunrise positions
     *
     * Update sunset position and offset settings. Closes issue #129 — use an automation to drive sunset_position from a sensor (e.g. mosquito activity). Pass null to clear an optional field.
     *
     * @param int|float|null $myPositionValue Somfy My position. The 'My' preset position (1–99%). Required when sunset_use_my or any custom_position_use_my is true. 1 to 99 %
     * @param ?bool $sunriseGatesStart Wait for sunrise before starting. If true, the operating window opens at the later of start time and sunrise (entity/astral + offset)
     * @param int|float|null $sunriseOffset Sunrise offset. Minutes to shift the start-of-window trigger relative to sunrise (-120–120). -120 to 120 minutes
     * @param int|float|null $sunsetOffset Sunset offset. Minutes to shift the end-of-window trigger relative to sunset (-120–120). -120 to 120 minutes
     * @param int|float|null $sunsetPosition Sunset position. Position to move to at end of time window. Null = use default_percentage. 0 to 100 %
     * @param ?bool $sunsetUseMy Use Somfy My position at sunset. If true, use my_position_value instead of sunset_position at end of window
     */
    public function setSunsetSunrise(
        ServiceTargetSource $target,
        int|float|null $myPositionValue = null,
        ?bool $sunriseGatesStart = null,
        int|float|null $sunriseOffset = null,
        int|float|null $sunsetOffset = null,
        int|float|null $sunsetPosition = null,
        ?bool $sunsetUseMy = null,
    ): EventContext {
        return $this->ha->callService('adaptive_cover_pro', 'set_sunset_sunrise', [
            'my_position_value' => $myPositionValue,
            'sunrise_gates_start' => $sunriseGatesStart,
            'sunrise_offset' => $sunriseOffset,
            'sunset_offset' => $sunsetOffset,
            'sunset_position' => $sunsetPosition,
            'sunset_use_my' => $sunsetUseMy,
        ], $target);
    }

    /**
     * Set tilt
     *
     * Set the slat/tilt axis of the targeted covers. On venetian (dual-axis) covers this drives ONLY the tilt slats and leaves the carriage untouched; on cover types whose primary axis already is the tilt it behaves like a tilt move. By default the call engages manual override; set force=true to skip manual-override engagement (matching set_position's force semantics).
     *
     * @param int|float $tilt Tilt. Target tilt (0–100%). 0 to 100 %
     * @param ?bool $force Force. When true, skip manual-override engagement. Default false — service calls engage manual override like a dashboard slider
     */
    public function setTilt(ServiceTargetSource $target, int|float $tilt, ?bool $force = null): EventContext
    {
        return $this->ha->callService('adaptive_cover_pro', 'set_tilt', [
            'tilt' => $tilt,
            'force' => $force,
        ], $target);
    }

    /**
     * Set venetian options
     *
     * Update venetian-blind specific options: operating mode, tilt skip threshold, and post-settle hold. Applicable to venetian cover types only.
     *
     * @param int|float|null $venetianBackrotatePublishLag Publish-lag window (s). Seconds the integration tolerates a late position/tilt-state publish from the actuator before treating it as a user touch (15–180 s). Default 45 s. Raise to 60–120 s for slow KNX bus or Fibaro/Shelly republish; tighten only for unusually fast actuators. 15 to 180 s
     * @param 'position_and_tilt'|'tilt_only'|null $venetianMode Venetian mode. Operating mode: 'position_and_tilt' (move carriage then tilt) or 'tilt_only' (tilt only, no carriage movement)
     * @param int|float|null $venetianPostSettleHold Post-settle hold (s). Seconds to wait after carriage stops before sending the tilt command (0.0–10.0 s). Raise to 4–6 s for KNX FGR223 firmware. 0 to 10 s
     * @param int|float|null $venetianTiltSkipAbove Tilt skip above (%). Skip tilt commands when carriage position exceeds this value (0–100%). Set to 100 to always tilt. 0 to 100 %
     */
    public function setVenetian(
        ServiceTargetSource $target,
        int|float|null $venetianBackrotatePublishLag = null,
        ?string $venetianMode = null,
        int|float|null $venetianPostSettleHold = null,
        int|float|null $venetianTiltSkipAbove = null,
    ): EventContext {
        return $this->ha->callService('adaptive_cover_pro', 'set_venetian', [
            'venetian_backrotate_publish_lag' => $venetianBackrotatePublishLag,
            'venetian_mode' => $venetianMode,
            'venetian_post_settle_hold' => $venetianPostSettleHold,
            'venetian_tilt_skip_above' => $venetianTiltSkipAbove,
        ], $target);
    }

    /**
     * Set weather safety settings
     *
     * Update wind, rain, and severe-weather override settings. The weather handler priority-overrides automatic control to protect covers from damage.
     *
     * @param ?bool $weatherBypassAutoControl Bypass automatic control. If true, weather override ignores the Automatic Control toggle
     * @param ?string $weatherIsRainingSensor Is raining sensor. Binary sensor indicating active rain. Null = none
     * @param ?string $weatherIsWindySensor Is windy sensor. Binary sensor indicating dangerous wind. Null = none
     * @param ?bool $weatherOutsideWindow Act outside the time window. If true (default), weather overrides keep acting after the time window closes. Set false to scope weather safety to the configured start/end window
     * @param ?bool $weatherOverrideMinMode Minimum position mode. If true, treat weather_override_position as a minimum floor
     * @param int|float|null $weatherOverridePosition Weather override position. Position to move to when a weather condition is triggered (0–100%). 0 to 100 %
     * @param int|float|null $weatherOverrideTilt Weather override tilt. Slat tilt to set when a weather condition is triggered (0–100%). Venetian blinds only; null = leave the slats alone. 0 to 100 %
     * @param ?string $weatherRainSensor Rain sensor. Sensor entity for rain accumulation. Null = none
     * @param int|float|null $weatherRainThreshold Rain threshold. Rain accumulation above which the cover is retracted. 0 to 100
     * @param list<string>|null $weatherSevereSensors Severe weather sensors. Binary sensors that indicate severe weather conditions (OR logic). Empty list = none
     * @param int|float|null $weatherTimeout Weather clear timeout. Seconds to wait after conditions clear before resuming automatic control (0–3600). 0 to 3600 seconds
     * @param ?string $weatherWindDirectionSensor Wind direction sensor. Sensor entity for wind direction (degrees). Null = none
     * @param int|float|null $weatherWindDirectionTolerance Wind direction tolerance. Degrees either side of the window azimuth within which wind is considered a threat (5–180°). 5 to 180 °
     * @param ?string $weatherWindSpeedSensor Wind speed sensor. Sensor entity for wind speed. Null = none
     * @param int|float|null $weatherWindSpeedThreshold Wind speed threshold. Wind speed above which the cover is retracted (units must match sensor). 0 to 200
     */
    public function setWeatherSafety(
        ServiceTargetSource $target,
        ?bool $weatherBypassAutoControl = null,
        ?string $weatherIsRainingSensor = null,
        ?string $weatherIsWindySensor = null,
        ?bool $weatherOutsideWindow = null,
        ?bool $weatherOverrideMinMode = null,
        int|float|null $weatherOverridePosition = null,
        int|float|null $weatherOverrideTilt = null,
        ?string $weatherRainSensor = null,
        int|float|null $weatherRainThreshold = null,
        ?array $weatherSevereSensors = null,
        int|float|null $weatherTimeout = null,
        ?string $weatherWindDirectionSensor = null,
        int|float|null $weatherWindDirectionTolerance = null,
        ?string $weatherWindSpeedSensor = null,
        int|float|null $weatherWindSpeedThreshold = null,
    ): EventContext {
        return $this->ha->callService('adaptive_cover_pro', 'set_weather_safety', [
            'weather_bypass_auto_control' => $weatherBypassAutoControl,
            'weather_is_raining_sensor' => $weatherIsRainingSensor,
            'weather_is_windy_sensor' => $weatherIsWindySensor,
            'weather_outside_window' => $weatherOutsideWindow,
            'weather_override_min_mode' => $weatherOverrideMinMode,
            'weather_override_position' => $weatherOverridePosition,
            'weather_override_tilt' => $weatherOverrideTilt,
            'weather_rain_sensor' => $weatherRainSensor,
            'weather_rain_threshold' => $weatherRainThreshold,
            'weather_severe_sensors' => $weatherSevereSensors,
            'weather_timeout' => $weatherTimeout,
            'weather_wind_direction_sensor' => $weatherWindDirectionSensor,
            'weather_wind_direction_tolerance' => $weatherWindDirectionTolerance,
            'weather_wind_speed_sensor' => $weatherWindSpeedSensor,
            'weather_wind_speed_threshold' => $weatherWindSpeedThreshold,
        ], $target);
    }

    /**
     * Stop cover
     *
     * Sends stop_cover to the targeted covers via the ACP proxy so the command is recognised as ACP-originated. Engages manual override so the next automatic cycle does not immediately counter-command the cover. Compatible with manual_ignore_external mode — the Lovelace card stop button should call this service instead of cover.stop_cover directly.
     */
    public function stop(ServiceTargetSource $target): EventContext
    {
        return $this->ha->callService('adaptive_cover_pro', 'stop', [], $target);
    }
}
